263	Describe 'Get-ComplianceSummary' {
264	    It 'counts statuses and flags compliance only when nothing is denied or unknown' {
265	        $report = @(
266	            [pscustomobject]@{ Name = 'a'; Version = '1'; License = 'MIT';     Status = 'approved' }
267	            [pscustomobject]@{ Name = 'b'; Version = '1'; License = 'MIT';     Status = 'approved' }
268	            [pscustomobject]@{ Name = 'c'; Version = '1'; License = 'GPL-3.0'; Status = 'denied' }
269	            [pscustomobject]@{ Name = 'd'; Version = '1'; License = 'UNKNOWN'; Status = 'unknown' }
270	        )
271	        $s = Get-ComplianceSummary -Report $report
272	        $s.Approved  | Should -Be 2
273	        $s.Denied    | Should -Be 1
274	        $s.Unknown   | Should -Be 1
275	        $s.Total     | Should -Be 4
276	        $s.Compliant | Should -BeFalse
277	    }
278	
279	    It 'is compliant when every dependency is approved' {
280	        $report = @(
281	            [pscustomobject]@{ Name = 'a'; Version = '1'; License = 'MIT'; Status = 'approved' }
282	            [pscustomobject]@{ Name = 'b'; Version = '1'; License = 'ISC'; Status = 'approved' }
283	        )
284	        $s = Get-ComplianceSummary -Report $report
285	        $s.Compliant | Should -BeTrue
286	        $s.Approved  | Should -Be 2
287	    }
288	
289	    It 'handles an empty report (vacuously compliant)' {
290	        $s = Get-ComplianceSummary -Report @()
291	        $s.Total     | Should -Be 0
292	        $s.Compliant | Should -BeTrue
293	    }
294	}
295	
296	Describe 'Format-ComplianceReport' {
297	    BeforeAll {
298	        $script:Report = @(
299	            [pscustomobject]@{ Name = 'express'; Version = '4.18.2'; License = 'MIT';     Status = 'approved' }
300	            [pscustomobject]@{ Name = 'evil';    Version = '1.0.0';  License = 'GPL-3.0'; Status = 'denied' }
301	            [pscustomobject]@{ Name = 'mystery'; Version = '2.0.0';  License = 'UNKNOWN'; Status = 'unknown' }
302	        )
303	        $script:Summary = [pscustomobject]@{
304	            Approved = 1; Denied = 1; Unknown = 1; Total = 3; Compliant = $false
305	        }
306	    }
307	
308	    It 'emits deterministic, parseable text lines' {
309	        $text = Format-ComplianceReport -Report $script:Report -Summary $script:Summary -Format text
310	        $text | Should -Match 'DEP name=express version=4.18.2 license=MIT status=approved'
311	        $text | Should -Match 'DEP name=evil version=1.0.0 license=GPL-3.0 status=denied'
312	        $text | Should -Match 'DEP name=mystery version=2.0.0 license=UNKNOWN status=unknown'
313	        $text | Should -Match 'RESULT approved=1 denied=1 unknown=1 total=3'
314	        $text | Should -Match 'COMPLIANCE: NON-COMPLIANT'
315	    }
316	
317	    It 'emits a COMPLIANT verdict when the summary is compliant' {
318	        $summary = [pscustomobject]@{ Approved = 3; Denied = 0; Unknown = 0; Total = 3; Compliant = $true }
319	        $text = Format-ComplianceReport -Report $script:Report -Summary $summary -Format text
320	        $text | Should -Match 'COMPLIANCE: COMPLIANT'
321	    }
322	
323	    It 'emits a GitHub-flavoured markdown table' {
324	        $md = Format-ComplianceReport -Report $script:Report -Summary $script:Summary -Format markdown
325	        $md | Should -Match '\| Dependency \| Version \| License \| Status \|'
326	        $md | Should -Match '\| express \| 4.18.2 \| MIT \| approved \|'
327	        $md | Should -Match 'NON-COMPLIANT'
328	    }
329	
330	    It 'emits valid JSON round-trippable back to the report rows' {
331	        $json = Format-ComplianceReport -Report $script:Report -Summary $script:Summary -Format json
332	        $obj = $json | ConvertFrom-Json
333	        $obj.summary.denied | Should -Be 1
334	        $obj.dependencies.Count | Should -Be 3
335	        $obj.dependencies[0].name | Should -Be 'express'
336	    }
337	}
